/* ── file map ─────────────────────────────────────────────────────────────────
 * exports    CONSUMER_WORDS
 * depends    —
 * used by    —
 * ─────────────────────────────────────────────── generated by `npm run map` ──
 */
/**
 * Rule 4: a consumer's vocabulary, never this package's.
 *
 * `tracker` and `site` only. `page`, `app` and `store` are deliberately absent even though an
 * earlier draft of the contract listed them: a wiki page is a real thing the game has, and
 * `itemsPerPage` is pagination. Banning a word with honest uses teaches everyone to ignore the
 * rule, and then it stops catching the words that have no honest use here.
 *
 * `SITE` and `Site` count only as a whole word segment — `SITE_TABLE`, `SPECIAL_SITE_LABELS`,
 * `fromSite`, a bare `SITE`. Matching them anywhere inside an identifier flagged `COMPOSITE`,
 * `OPPOSITE`, `PREREQUISITES` and `randomBasicCallSites`, none of which name a website, and a rule
 * that mostly reports false positives is a rule nobody reads.
 *
 * A call site and a gate site are places in the game's code — `CALL_SITE_COUNT`, `GATE_SITE`,
 * `callSite` — so a segment directly after `CALL`/`GATE` is the programming term, not a website.
 */
export const CONSUMER_WORDS = new RegExp(
  [
    String.raw`\b(?:tracker|Tracker|TRACKER)\b`,
    // `Tracker` as a camelCase segment too: `VaultV29TrackerTarget` passed the whole-word form.
    String.raw`\b[A-Za-z0-9]*[a-z0-9]Tracker(?![a-z])[A-Za-z0-9_]*\b`,
    String.raw`\b(?:[A-Z0-9]+_)+TRACKER(?:_[A-Z0-9]+)*\b`,
    // camelCase segment: `Site` not followed by a lower-case letter (`fromSite`, `SiteLabs`).
    String.raw`\b(?:[A-Za-z0-9]*[a-z0-9])?(?<![Cc]all|[Gg]ate)Site(?![a-z])[A-Za-z0-9_]*\b`,
    // UPPER_SNAKE segment: `SITE` bounded by underscores or the ends of the word.
    String.raw`\b(?:[A-Z0-9]+_)*(?<!CALL_|GATE_)SITE(?:_[A-Z0-9]+)*\b`,
  ].join('|'),
  'g',
)
